lorenzSol = NDSolveValue[{x'[t] == 10 (y[t] - x[t]), y'[t] == x[t] (28 - z[t]) - y[t], z'[t] == x[t] y[t] - (8/3) z[t], x[0] == 1, y[0] == 1, z[0] == 1}, {x, y, z}, {t, 0, 40}, MaxStepSize -> 0.01];
series = Table[Through[lorenzSol[t]], {t, 0, 40, 0.01}];
phasePlot = ListLinePlot[series[[All, {1, 2}]], Frame -> True, FrameLabel -> {"x", "y"}, PlotLabel -> "Lorenz"];
tangentSol = NDSolveValue[{x'[t] == 10 (y[t] - x[t]), y'[t] == x[t] (28 - z[t]) - y[t], z'[t] == x[t] y[t] - (8/3) z[t], dx'[t] == -10 dx[t] + 10 dy[t], dy'[t] == (28 - z[t]) dx[t] - dy[t] - x[t] dz[t], dz'[t] == y[t] dx[t] + x[t] dy[t] - (8/3) dz[t], x[0] == 1, y[0] == 1, z[0] == 1, dx[0] == 1*^-8, dy[0] == 0, dz[0] == 0}, {dx, dy, dz}, {t, 0, 40}, MaxStepSize -> 0.01];
tangentNorm = Sqrt[Through[tangentSol[40.]] . Through[tangentSol[40.]]];
lyapunovMax = Log[tangentNorm/1*^-8]/40.;
xRange = MinMax[series[[All, 1]]];
